/**
 * Westlake (ADR-0003): Android user ids map to host identities explicitly, not by division. The host
 * numbers an OS account's uids from its own base (OpenHarmony: 200000 per account), so a host uid divided
 * by PER_USER_RANGE gives a number (200 for OpenHarmony's account 100) that is no Android user, and
 * UserManager.isSystemUser() said false in every app. An app sees its own host user as Android user 0,
 * the system user, as on a phone; uids stay the host's, other host users keep their numbers.
 */
private static int westlakeAndroidUser(int hostUser) {
    return hostUser != USER_SYSTEM && hostUser == Process.myUid() / PER_USER_RANGE ? USER_SYSTEM : hostUser;
}

/** Westlake: the host user that Android user id userId names for appId (see westlakeAndroidUser). */
private static int westlakeHostUser(int userId, int appId) {
    if (userId != USER_SYSTEM || appId % PER_USER_RANGE < Process.FIRST_APPLICATION_UID) return userId;
    return Process.myUid() / PER_USER_RANGE;
}

